//! The runtime shared by every Zig binding generated by uniffi-bindgen-zig.
//!
//! Ownership, everywhere in the generated API:
//!   - arguments are borrowed: the bindings copy what they need during the call;
//!   - a function whose result (or error payload) holds heap memory takes an
//!     `allocator` first and allocates the result with it; the caller frees it
//!     (records and enums have `deinit(allocator)`);
//!   - every call can fail with `uniffi.Error`; after `error.RustPanic` the
//!     message is in `uniffi.lastErrorMessage()`.
const std = @import("std");

/// UniFFI's buffer type (uniffi 0.32).
pub const RustBuffer = extern struct {
    capacity: u64 = 0,
    len: u64 = 0,
    data: ?[*]u8 = null,
};

/// Bytes lent to Rust for the length of a call.
pub const ForeignBytes = extern struct {
    len: i32,
    data: ?[*]const u8,
};

pub const RustCallStatus = extern struct {
    code: i8 = 0,
    error_buf: RustBuffer = .{},
};

pub const call_success: i8 = 0;
pub const call_error: i8 = 1;
pub const call_unexpected_error: i8 = 2;
pub const call_cancelled: i8 = 3;

/// The ways any call can fail besides its declared error type.
pub const Error = error{
    /// Rust panicked; see `lastErrorMessage()`.
    RustPanic,
    /// The async call was cancelled.
    Cancelled,
    /// The bindings failed: a corrupt buffer, a stale handle, a version mismatch.
    Internal,
    OutOfMemory,
};

/// A point in time: `secs` seconds (negative before 1970) plus `nanos`
/// nanoseconds (0..999_999_999) after the Unix epoch.
pub const Timestamp = struct {
    secs: i64,
    nanos: u32 = 0,
};

/// A span of time: `secs` seconds plus `nanos` nanoseconds (0..999_999_999).
pub const Duration = struct {
    secs: u64,
    nanos: u32 = 0,
};

/// One entry of a map.
pub fn Entry(comptime K: type, comptime V: type) type {
    return struct {
        key: K,
        value: V,
    };
}

threadlocal var message_buf: [4096]u8 = undefined;
threadlocal var message_len: usize = 0;

/// The message of the last `error.RustPanic` (or `error.Internal`) on this thread.
pub fn lastErrorMessage() []const u8 {
    return message_buf[0..message_len];
}

pub fn setLastErrorMessage(text: []const u8) void {
    const n = @min(text.len, message_buf.len);
    @memcpy(message_buf[0..n], text[0..n]);
    message_len = n;
}

/// The allocator the bindings use for scratch buffers and for what they lend
/// to callbacks.
pub const allocator = std.heap.c_allocator;

// ---------------------------------------------------------------------------
// Serialization: big-endian, as UniFFI writes RustBuffers.
// ---------------------------------------------------------------------------

pub const Writer = struct {
    list: std.ArrayList(u8) = .empty,

    pub fn deinit(w: *Writer) void {
        w.list.deinit(allocator);
    }

    pub fn raw(w: *Writer, bytes: []const u8) void {
        w.list.appendSlice(allocator, bytes) catch oom();
    }

    pub fn int(w: *Writer, comptime T: type, v: T) void {
        var buf: [@sizeOf(T)]u8 = undefined;
        std.mem.writeInt(T, &buf, v, .big);
        w.raw(&buf);
    }

    pub fn boolean(w: *Writer, v: bool) void {
        w.int(i8, if (v) 1 else 0);
    }

    pub fn float32(w: *Writer, v: f32) void {
        w.int(u32, @bitCast(v));
    }

    pub fn float64(w: *Writer, v: f64) void {
        w.int(u64, @bitCast(v));
    }

    pub fn len(w: *Writer, n: usize) void {
        if (n > std.math.maxInt(i32)) @panic("uniffi: a string, byte string or collection is longer than 2^31-1");
        w.int(i32, @intCast(n));
    }

    pub fn string(w: *Writer, v: []const u8) void {
        w.len(v.len);
        w.raw(v);
    }

    /// UniFFI writes a timestamp before 1970 as the negated duration before the epoch.
    pub fn timestamp(w: *Writer, v: Timestamp) void {
        if (v.secs >= 0 or v.nanos == 0) {
            w.int(i64, v.secs);
            w.int(u32, v.nanos);
        } else {
            w.int(i64, v.secs + 1);
            w.int(u32, 1_000_000_000 - v.nanos);
        }
    }

    pub fn duration(w: *Writer, v: Duration) void {
        w.int(u64, v.secs);
        w.int(u32, v.nanos);
    }
};

pub const Reader = struct {
    data: []const u8,
    pos: usize = 0,

    pub fn remaining(r: *const Reader) usize {
        return r.data.len - r.pos;
    }

    fn take(r: *Reader, n: usize) Error![]const u8 {
        if (r.remaining() < n) return error.Internal;
        defer r.pos += n;
        return r.data[r.pos..][0..n];
    }

    pub fn int(r: *Reader, comptime T: type) Error!T {
        const bytes = try r.take(@sizeOf(T));
        return std.mem.readInt(T, bytes[0..@sizeOf(T)], .big);
    }

    pub fn boolean(r: *Reader) Error!bool {
        return switch (try r.int(i8)) {
            0 => false,
            1 => true,
            else => error.Internal,
        };
    }

    pub fn float32(r: *Reader) Error!f32 {
        return @bitCast(try r.int(u32));
    }

    pub fn float64(r: *Reader) Error!f64 {
        return @bitCast(try r.int(u64));
    }

    /// A length prefix. Each element takes at least `min_item_size` bytes, so a
    /// length the rest of the buffer cannot hold is rejected before allocating.
    pub fn len(r: *Reader, min_item_size: usize) Error!usize {
        const n = try r.int(i32);
        if (n < 0) return error.Internal;
        const count: usize = @intCast(n);
        if (min_item_size > 0 and count > r.remaining() / min_item_size) return error.Internal;
        return count;
    }

    pub fn string(r: *Reader, a: std.mem.Allocator) Error![]const u8 {
        const n = try r.len(1);
        return try a.dupe(u8, try r.take(n));
    }

    pub fn timestamp(r: *Reader) Error!Timestamp {
        const secs = try r.int(i64);
        const nanos = try r.int(u32);
        if (nanos > 999_999_999) return error.Internal;
        if (secs >= 0 or nanos == 0) return .{ .secs = secs, .nanos = nanos };
        return .{ .secs = secs - 1, .nanos = 1_000_000_000 - nanos };
    }

    pub fn duration(r: *Reader) Error!Duration {
        const secs = try r.int(u64);
        const nanos = try r.int(u32);
        if (nanos > 999_999_999) return error.Internal;
        return .{ .secs = secs, .nanos = nanos };
    }
};

pub fn oom() noreturn {
    @panic("uniffi: out of memory");
}

// ---------------------------------------------------------------------------
// Call status.
// ---------------------------------------------------------------------------

/// Turns a non-success, non-error status into the matching `Error`, keeping
/// Rust's message. `free_buffer` releases the error buffer.
pub fn unexpected(status: *const RustCallStatus, free_buffer: *const fn (RustBuffer) void) Error {
    switch (status.code) {
        call_cancelled => {
            setLastErrorMessage("the call was cancelled");
            return error.Cancelled;
        },
        call_unexpected_error => {
            const buf = status.error_buf;
            if (buf.data) |data| {
                setLastErrorMessage(data[0..@intCast(buf.len)]);
            } else {
                setLastErrorMessage("Rust panicked");
            }
            free_buffer(buf);
            return error.RustPanic;
        },
        else => {
            setLastErrorMessage("unknown call status");
            return error.Internal;
        },
    }
}

/// The status a C-implemented callback reports when it fails unexpectedly.
pub fn callbackPanic(status: *RustCallStatus, message: []const u8, from_bytes: *const fn ([]const u8) RustBuffer) void {
    status.code = call_unexpected_error;
    status.error_buf = from_bytes(message);
}

// ---------------------------------------------------------------------------
// Threads: pthreads (the bindings link libc, as the Rust library does).
// ---------------------------------------------------------------------------

pub const Mutex = struct {
    inner: std.c.pthread_mutex_t = std.c.PTHREAD_MUTEX_INITIALIZER,

    pub fn lock(m: *Mutex) void {
        _ = std.c.pthread_mutex_lock(&m.inner);
    }

    pub fn unlock(m: *Mutex) void {
        _ = std.c.pthread_mutex_unlock(&m.inner);
    }
};

pub const Condition = struct {
    inner: std.c.pthread_cond_t = std.c.PTHREAD_COND_INITIALIZER,

    pub fn wait(c: *Condition, m: *Mutex) void {
        _ = std.c.pthread_cond_wait(&c.inner, &m.inner);
    }

    pub fn broadcast(c: *Condition) void {
        _ = std.c.pthread_cond_broadcast(&c.inner);
    }
};

/// Runs `function(args)` on a new detached thread.
pub fn spawn(comptime function: anytype, args: anytype) void {
    const thread = std.Thread.spawn(.{}, function, args) catch @panic("uniffi: could not start a thread");
    thread.detach();
}

// ---------------------------------------------------------------------------
// Rust futures: polled until ready, blocking the calling thread.
// ---------------------------------------------------------------------------

pub const ContinuationCallback = *const fn (u64, i8) callconv(.c) void;
pub const PollFn = *const fn (u64, ContinuationCallback, u64) callconv(.c) void;

const Waiter = struct {
    mutex: Mutex = .{},
    cond: Condition = .{},
    woken: bool = false,
    poll_result: i8 = 0,
};

fn continuation(data: u64, poll_result: i8) callconv(.c) void {
    const w: *Waiter = @ptrFromInt(@as(usize, @intCast(data)));
    w.mutex.lock();
    defer w.mutex.unlock();
    w.poll_result = poll_result;
    w.woken = true;
    w.cond.broadcast();
}

/// Polls the Rust future `future` until it is ready.
pub fn blockOn(future: u64, poll: PollFn) void {
    var w: Waiter = .{};
    while (true) {
        w.woken = false;
        poll(future, continuation, @intFromPtr(&w));
        w.mutex.lock();
        while (!w.woken) w.cond.wait(&w.mutex);
        const result = w.poll_result;
        w.mutex.unlock();
        if (result == 0) break; // ready
    }
}

// ---------------------------------------------------------------------------
// Handle maps: Zig implementations of callback interfaces and traits, by the
// odd handles Rust holds (Rust's own handles are even).
// ---------------------------------------------------------------------------

pub fn HandleMap(comptime T: type) type {
    return struct {
        const Self = @This();
        const Shared = struct {
            value: T,
            refs: usize,
        };

        mutex: Mutex = .{},
        map: std.AutoHashMapUnmanaged(u64, *Shared) = .empty,
        next: u64 = 1,

        fn put(self: *Self, shared: *Shared) u64 {
            const handle = self.next;
            self.next += 2;
            self.map.put(allocator, handle, shared) catch oom();
            return handle;
        }

        /// Stores `value` under a new odd handle.
        pub fn insert(self: *Self, value: T) u64 {
            const shared = allocator.create(Shared) catch oom();
            shared.* = .{ .value = value, .refs = 1 };
            self.mutex.lock();
            defer self.mutex.unlock();
            return self.put(shared);
        }

        /// The value behind `handle`, or null when it is unknown.
        pub fn get(self: *Self, handle: u64) ?T {
            self.mutex.lock();
            defer self.mutex.unlock();
            const shared = self.map.get(handle) orelse return null;
            return shared.value;
        }

        /// A new handle to the same value, or 0 when `handle` is unknown.
        pub fn clone(self: *Self, handle: u64) u64 {
            self.mutex.lock();
            defer self.mutex.unlock();
            const shared = self.map.get(handle) orelse return 0;
            shared.refs += 1;
            return self.put(shared);
        }

        /// Drops `handle`. Returns the value when that was its last handle (the
        /// caller then releases it), null otherwise.
        pub fn remove(self: *Self, handle: u64) ?T {
            self.mutex.lock();
            defer self.mutex.unlock();
            const entry = self.map.fetchRemove(handle) orelse return null;
            const shared = entry.value;
            shared.refs -= 1;
            if (shared.refs > 0) return null;
            const value = shared.value;
            allocator.destroy(shared);
            return value;
        }
    };
}

test "writer and reader round trip" {
    var w: Writer = .{};
    defer w.deinit();
    w.int(i32, -7);
    w.string("héllo");
    w.timestamp(.{ .secs = -2, .nanos = 500_000_000 });
    w.boolean(true);
    w.float64(2.5);
    var r: Reader = .{ .data = w.list.items };
    try std.testing.expectEqual(@as(i32, -7), try r.int(i32));
    const s = try r.string(std.testing.allocator);
    defer std.testing.allocator.free(s);
    try std.testing.expectEqualStrings("héllo", s);
    try std.testing.expectEqual(Timestamp{ .secs = -2, .nanos = 500_000_000 }, try r.timestamp());
    try std.testing.expect(try r.boolean());
    try std.testing.expectEqual(@as(f64, 2.5), try r.float64());
    try std.testing.expectEqual(@as(usize, 0), r.remaining());
}

test "reader rejects lengths the buffer cannot hold" {
    var r: Reader = .{ .data = &.{ 0x7f, 0xff, 0xff, 0xff } };
    try std.testing.expectError(error.Internal, r.len(1));
    var bad_bool: Reader = .{ .data = &.{2} };
    try std.testing.expectError(error.Internal, bad_bool.boolean());
}

test "handle map hands out odd handles and frees on the last drop" {
    var map: HandleMap(u32) = .{};
    const a = map.insert(7);
    try std.testing.expect(a & 1 == 1);
    const b = map.clone(a);
    try std.testing.expect(b != a and b & 1 == 1);
    try std.testing.expectEqual(@as(?u32, 7), map.get(b));
    try std.testing.expectEqual(@as(?u32, null), map.remove(a));
    try std.testing.expectEqual(@as(?u32, 7), map.remove(b));
    try std.testing.expectEqual(@as(?u32, null), map.get(b));
    map.map.deinit(allocator);
}
